namespace sv_d3c8fe06ad014385a45fb9fdae016119.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_d3c8fe06ad014385a45fb9fdae016119.Components.Pages.Settings

<nav class="settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_d3c8fe06ad014385a45fb9fdae016119.Components.Pages.Settings
@using sv_d3c8fe06ad014385a45fb9fdae016119.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile</h2>

    @if (isLoading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@avatarUrl" alt="Avatar" class="avatar-image" />
            <p class="avatar-url">@avatarUrl</p>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="displayName" class="form-control" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="email" class="form-control" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="bio" class="form-control" rows="4"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">Profile saved successfully!</div>
        }
    }
</div>

@code {
    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";

    private UserProfile? savedProfile;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        avatarUrl = profile.AvatarUrl;
        bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        var updated = new UserProfile(displayName, email, avatarUrl, bio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        isSaving = false;
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
    }
}

@namespace sv_d3c8fe06ad014385a45fb9fdae016119.Components.Pages.Settings
@using sv_d3c8fe06ad014385a45fb9fdae016119.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notifications</h2>

    @if (isLoading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="emailNotifications" />
                <span>Email Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="pushNotifications" />
                <span>Push Notifications</span>
            </label>

            <label class="toggle-item">
                <input type="checkbox" @bind="weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in allChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (showSuccess)
        {
            <div class="toast success">Preferences saved successfully!</div>
        }
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];

    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        isSaving = false;
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_d3c8fe06ad014385a45fb9fdae016119.Components.Pages.Settings
@using sv_d3c8fe06ad014385a45fb9fdae016119.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security</h2>

    @if (isLoading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(passwordPanelOpen ? "▼" : "▶")</span>
            </button>

            @if (passwordPanelOpen)
            {
                <div class="panel-content">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" class="form-control" />
                    </div>

                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <p class="error-message">@passwordError</p>
                    }
                    @if (passwordSuccess)
                    {
                        <p class="success-message">Password updated successfully!</p>
                    }

                    <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="twofa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="twofa-status">
                <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                    @(twoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
                <label class="toggle-item">
                    <input type="checkbox" @bind="twoFactorEnabled" />
                    <span>Enable 2FA</span>
                </label>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != sessions.FirstOrDefault())
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay">
                <div class="dialog">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private bool isLoading = true;
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = new();

    // Password change
    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool passwordSuccess;
    private bool isChangingPassword;

    // Session revoke
    private ActiveSession? sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = settings.Sessions;
        isLoading = false;
    }

    private async Task UpdatePassword()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        isChangingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            passwordSuccess = true;
            currentPassword = "";
